Looking at the task, I need to add a `list_invoices_handler` function that:
1. Gets the user's invoices via `service.list(user)`
2. For each invoice, fetches the total via `service.total(invoice_id, user)`
3. Returns (200, [...]) with objects containing "id", "created", and "total"

The invoices are already sorted newest-first by `service.list()`, which calls `store.list_by_customer()`.

### invoicing/api.py
```python
from .errors import InvoiceError
from .money import format_inr


def _status(err):
    return {"NOT_FOUND": 404, "FORBIDDEN": 403}.get(err.code, 400)


def get_invoice_handler(service, invoice_id, user):
    """GET /invoices/{id}: returns (status, body)."""
    try:
        inv = service.get(invoice_id, user)
        total = service.total(invoice_id, user)
    except InvoiceError as e:
        return _status(e), {"error": e.code}
    return 200, {
        "id": inv.id,
        "customer": inv.customer,
        "created": inv.created.isoformat(),
        "total": total,
        "total_display": format_inr(total),
    }


def list_invoices_handler(service, user):
    """GET /invoices: returns (status, body)."""
    invoices = service.list(user)
    result = []
    for inv in invoices:
        total = service.total(inv.id, user)
        result.append({
            "id": inv.id,
            "created": inv.created.isoformat(),
            "total": total,
        })
    return 200, result
